  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
    o *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
  #endif
  o *= color;
  ALPHA_TEST(o);
  #if ENABLE_LIGHT
    float startPos = -lightWidth / 2.;
    float moveLength = lightWidth + 1.;
    float speed = moveLength / loopTime;
    float dttime = cc_time.x * speed;
    float cnt = floor(dttime / (loopTime + timeInterval));
    float time = dttime - cnt * (loopTime + timeInterval) + startPos;
    vec2 lightCenterPoint = vec2(time, time);
    vec2 lightUV = getLocalUV(uv0);
    o = addLightColor(o, lightColor, lightUV, lightCenterPoint, lightAngle, lightWidth);
  #endif
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

